SET TRANSACTION READ ONLY;SET LOCAL statement_timeout='150s';SET LOCAL ROLE needacabplus_shared_reader;
DO $$ DECLARE result jsonb;BEGIN
WITH m AS MATERIALIZED(SELECT "externalId",status,"bookingSource" source,CASE WHEN distance IS NULL AND "systemDistance" IS NULL AND "meterDistance" IS NULL AND "meterDistanceMetres" IS NULL AND "gpsMeterDistance" IS NULL AND "estimatedDistance" IS NULL THEN 'all_null' ELSE 'zero_or_nonpositive' END cohort FROM "Booking" WHERE greatest(COALESCE(distance,0),COALESCE("systemDistance",0),COALESCE("meterDistance",0),COALESCE("meterDistanceMetres",0),COALESCE("gpsMeterDistance",0),COALESCE("estimatedDistance",0))<=0),
a AS MATERIALIZED(SELECT m.*,e.autocab_id,e.archive_reason,e.archived_booking#>>'{systemDistance,asMiles}' system_miles,e.pricing#>>'{meterDistance,asMiles}' meter_miles,e.raw_payload->>'distance' route_distance,
 e.archived_booking#>>'{driver,id}' driver_id,e.archived_booking#>>'{driver,callsign}' callsign,
 e.archived_booking->>'dispatchedAtTime' dispatch,e.archived_booking->>'pickedUpAtTime' pob,e.archived_booking->>'completedAtTime' completed
 FROM m LEFT JOIN LATERAL(SELECT autocab_id,archive_reason,archived_booking,pricing,raw_payload FROM autocab_history.entries e WHERE e.original_booking_id=m."externalId" ORDER BY e.archived_booking->>'archiveTime' DESC NULLS LAST,e.autocab_id DESC LIMIT 1)e ON true),
f AS MATERIALIZED(SELECT *,CASE WHEN system_miles~'^[0-9]+([.][0-9]+)?$' THEN system_miles::numeric END system_value,CASE WHEN meter_miles~'^[0-9]+([.][0-9]+)?$' THEN meter_miles::numeric END meter_value,CASE WHEN route_distance~'^[0-9]+([.][0-9]+)?$' THEN route_distance::numeric END route_value,
 (coalesce(nullif(nullif(btrim(driver_id),''),'0'),nullif(nullif(btrim(callsign),''),'0')) IS NOT NULL) archive_driver,
 dispatch IS NOT NULL AND dispatch NOT LIKE '0001-%' archive_dispatch,pob IS NOT NULL AND pob NOT LIKE '0001-%' archive_pob,completed IS NOT NULL AND completed NOT LIKE '0001-%' archive_completed FROM a)
SELECT jsonb_build_object(
 'cohorts',(SELECT jsonb_agg(x) FROM(SELECT cohort,count(*) jobs,count(autocab_id) archive_matches,count(*)FILTER(WHERE system_value>0) system_positive,count(*)FILTER(WHERE meter_value>0) meter_positive,count(*)FILTER(WHERE route_value>0) route_positive,count(*)FILTER(WHERE system_value>0 OR meter_value>0 OR route_value>0) any_archive_positive,count(*)FILTER(WHERE archive_driver) archive_driver,count(*)FILTER(WHERE archive_dispatch) archive_dispatch,count(*)FILTER(WHERE archive_pob) archive_pob,count(*)FILTER(WHERE archive_completed) archive_completed FROM f GROUP BY cohort)x),
 'sources',(SELECT jsonb_agg(x) FROM(SELECT source,count(*) jobs,count(autocab_id) archive_matches,count(*)FILTER(WHERE system_value>0) system_positive,count(*)FILTER(WHERE meter_value>0) meter_positive,count(*)FILTER(WHERE system_value>0 OR meter_value>0 OR route_value>0) any_archive_positive,count(*)FILTER(WHERE archive_driver) archive_driver,count(*)FILTER(WHERE archive_dispatch) archive_dispatch,count(*)FILTER(WHERE archive_pob) archive_pob FROM f GROUP BY source ORDER BY 2 DESC)x),
 'completed_outcome',(SELECT jsonb_agg(x) FROM(SELECT cohort,archive_reason,count(*) jobs,count(*)FILTER(WHERE system_value>0 OR meter_value>0 OR route_value>0) any_archive_positive FROM f WHERE status='COMPLETED' GROUP BY 1,2 ORDER BY 1,3 DESC)x)
) INTO result;RAISE NOTICE 'NO_POSITIVE_ARCHIVE_POPULATION %',result;END $$;
